SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for announcements
-- ----------------------------
DROP TABLE IF EXISTS `announcements`;
CREATE TABLE `announcements`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告内容',
  `type` enum('system','event','maintenance','update') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'system' COMMENT '公告类型',
  `priority` int NULL DEFAULT 0 COMMENT '优先级，数字越大越靠前',
  `status` enum('draft','published','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'draft' COMMENT '状态',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_publish_time`(`publish_time` ASC) USING BTREE,
  INDEX `idx_priority`(`priority` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '公告表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of announcements
-- ----------------------------
INSERT INTO `announcements` VALUES (1, '欢迎来到游戏评论平台', '欢迎各位玩家加入我们的游戏评论社区！在这里你可以发现优质游戏，分享游戏体验，与其他玩家交流心得。', 'system', 100, 'published', '2026-01-20 23:30:11', '2026-01-20 23:30:11', '2026-01-20 23:30:11');
INSERT INTO `announcements` VALUES (2, '新功能上线通知', '平台新增了游戏收藏功能，现在你可以收藏喜欢的游戏，方便随时查看！同时优化了评分系统，让评价更加精准。', 'update', 90, 'published', '2026-01-20 23:30:11', '2026-01-20 23:30:11', '2026-01-20 23:30:11');
INSERT INTO `announcements` VALUES (3, '社区规范提醒', '为了营造良好的社区氛围，请各位玩家文明发言，理性评论。禁止发布违规内容，违规用户将被封禁账号。', 'system', 80, 'published', '2026-01-20 23:30:11', '2026-01-20 23:30:11', '2026-01-20 23:30:11');
INSERT INTO `announcements` VALUES (4, '周末活动预告', '本周末将举办\"最佳游戏评论\"活动，优质评论将获得平台勋章奖励！快来参与吧！', 'event', 70, 'published', '2026-01-18 23:30:11', '2026-01-20 23:30:11', '2026-01-20 23:30:11');
INSERT INTO `announcements` VALUES (5, '系统维护通知', '系统将于本周日凌晨2:00-4:00进行例行维护，届时将无法访问，请各位玩家提前安排游戏时间。', 'maintenance', 60, 'published', '2026-01-15 23:30:11', '2026-01-20 23:30:11', '2026-01-20 23:30:11');
INSERT INTO `announcements` VALUES (6, '关于评选2025年度游戏的公告', '各游戏研发企业、发行机构、行业同仁及广大游戏爱好者：\n为梳理2025年度游戏行业发展成果，表彰在创意创新、技术突破、内容品质、用户口碑等方面表现突出的游戏作品与相关单位/个人，引领行业向精品化、正能量、高质量方向发展，搭建行业交流与学习的优质平台，经研究决定，正式启动2025年度游戏评选工作。现将有关事项公告如下：\n\n一、评选宗旨\n\n坚持“公平、公正、公开、择优”原则，以“赋能行业创新，传递游戏价值”为核心，聚焦游戏作品的思想性、艺术性、趣味性与技术性，挖掘兼具文化内涵与市场潜力的优质游戏，激励游戏从业者坚守初心、深耕创作，推动游戏行业健康可持续发展，为广大游戏用户提供更优质的娱乐体验。\n\n二、评选范围\n\n2025年1月1日至2025年12月31日期间，在中国大陆地区正式上线（含公测、正式发行）的各类游戏作品（包括客户端游戏、移动端游戏、主机游戏、网页游戏等），且符合国家相关法律法规及行业监管要求，无重大违法违规记录、无严重用户投诉及负面舆情。\n\n三、评选奖项\n\n本次评选设置以下核心奖项（可根据实际情况调整补充）：\n\n1. 年度最佳游戏（综合类最高奖项）\n\n2. 年度最佳创意游戏\n\n3. 年度最佳技术突破游戏\n\n4. 年度最佳内容品质游戏\n\n5. 年度最受欢迎游戏（用户投票类）\n\n6. 年度最佳独立游戏\n\n7. 年度最佳国产游戏\n\n8. 年度最佳海外引进游戏\n\n9. 年度游戏最佳研发团队\n\n10. 年度游戏最佳发行团队\n\n四、评选标准\n\n本次评选将结合专家评审与用户投票（部分奖项），从以下维度综合考评：\n\n1. 合规性：严格遵守《网络游戏管理暂行办法》《网络安全法》等国家法律法规及行业政策，内容无低俗、暴力、违法违规等不良元素，具备完整的版号等相关资质。\n\n2. 创意性：核心玩法、剧情设定、美术风格等方面具有独特创新，突破行业同质化瓶颈，为行业发展提供新思路。\n\n3. 技术性：在引擎技术、画面渲染、网络优化、兼容性等方面表现优异，具备技术领先性或行业标杆意义。\n\n4. 内容品质：剧情逻辑完整、角色塑造鲜明、美术设计精良、音效适配协调，整体内容兼具艺术性与观赏性，传递正向价值观。\n\n5. 用户口碑：上线后用户评价良好，评分稳定在合理区间，无大规模负面投诉，用户留存率、活跃度等核心数据表现突出（用户投票类奖项重点参考）。\n\n6. 行业价值：对游戏行业细分领域发展具有推动作用，或在文化传播、公益赋能等方面取得显著成效，具备良好的社会影响力。\n\n五、评选流程\n\n1. 报名阶段（XXXX年XX月XX日-XXXX年XX月XX日）：符合评选范围的游戏研发/发行单位，可通过指定官方渠道提交报名材料（包括报名表、游戏资质文件、作品介绍、核心亮点说明、相关数据证明等，具体材料清单另行通知）。\n\n2. 初审阶段（XXXX年XX月XX日-XXXX年XX月XX日）：评选组委会对报名材料进行审核，核对资质信息、筛选符合条件的候选作品/单位，公示初审合格名单。\n\n3. 评审与投票阶段（XXXX年XX月XX日-XXXX年XX月XX日）：组织行业专家、媒体代表组成评审团，对候选对象进行专业评审；同时开放官方投票通道，接受广大游戏用户投票（部分奖项结合专家评审得分与用户投票得分综合评定）。\n\n4. 终审与公示阶段（XXXX年XX月XX日-XXXX年XX月XX日）：结合专家评审结果与用户投票情况（如需），确定最终获奖名单，并在官方平台进行公示，公示期为5个工作日。公示期间接受异议反馈，对异议情况进行核查处理。\n\n5. 表彰阶段（XXXX年XX月XX日）：举办表彰仪式，正式公布获奖名单，为获奖作品/单位颁发荣誉证书及奖项，同步在官方渠道宣传报道。\n\n六、报名方式\n\n1.  报名渠道：本次评选仅接受官方指定线上报名端口提交材料，报名端口链接：【请填写官方报名链接】，咨询邮箱：【请填写官方咨询邮箱】，咨询电话：【请填写官方咨询电话】（工作日9:00-17:30）。\n\n2.  材料要求：报名材料需真实、完整、有效，复印件需加盖单位公章（电子版需加盖电子公章），逾期提交、材料不全或不符合要求的，视为无效报名。\n\n3.  注意事项：同一游戏作品可申报多个符合条件的奖项，但需分别提交对应报名材料；严禁弄虚作假、恶意刷票等违规行为，一经查实，取消参评资格及获奖资格，并在行业内通报。\n\n七、其他事项\n\n1.  本次评选不收取任何报名费用，评选过程严格遵守相关法律法规及行业规范，确保评选结果的公正性与权威性。\n\n2.  评选组委会有权对报名材料进行审核与核实，对符合要求的材料予以留存，用于本次评选相关的宣传推广工作（无需另行告知报名单位）。\n\n3.  本公告未尽事宜，由2025年度游戏评选组委会负责解释，后续将根据评选进展发布相关补充通知，请持续关注官方平台动态。\n\n特此公告。\n\n2025年度游戏评选组委会\n\nXXXX年XX月XX日', 'event', 5, 'published', '2026-01-21 23:12:57', '2026-01-21 15:13:18', '2026-01-21 15:13:18');

-- ----------------------------
-- Table structure for banners
-- ----------------------------
DROP TABLE IF EXISTS `banners`;
CREATE TABLE `banners`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `image_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '图片地址',
  `link_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '跳转链接',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序（数字越小越靠前）',
  `status` enum('active','inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'active' COMMENT '状态',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_sort_order`(`sort_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '轮播图表' ROW_FORMAT = DYNAMIC;

