-- ----------------------------
-- Table structure for comments
-- ----------------------------
DROP TABLE IF EXISTS `comments`;
CREATE TABLE `comments`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `game_id` int NOT NULL COMMENT '游戏id',
  `user_id` int NOT NULL COMMENT '用户id',
  `parent_id` int NULL DEFAULT NULL COMMENT '评论父id',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论内容',
  `likes_count` int NULL DEFAULT 0 COMMENT '点赞数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` enum('normal','reported','deleted') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'normal' COMMENT '状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_game`(`game_id` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_parent`(`parent_id` ASC) USING BTREE,
  CONSTRAINT `comments_ibfk_1` FOREIGN KEY (`game_id`) REFERENCES `games` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `comments_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `comments_ibfk_3` FOREIGN KEY (`parent_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '评论表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of comments
-- ----------------------------
INSERT INTO `comments` VALUES (1, 1, 2, NULL, '这是我玩过最好的魂系游戏！开放世界的设计让探索变得更加有趣，每个角落都有惊喜。虽然难度很高，但是击败Boss后的成就感无与伦比。', 46, '2026-01-20 20:26:21', '2026-01-20 13:33:57', 'normal');
INSERT INTO `comments` VALUES (2, 1, 3, NULL, '画面精美，世界观宏大，但是对新手不太友好。建议先玩过其他魂系游戏再来挑战。', 23, '2026-01-20 20:26:21', '2026-01-20 13:34:10', 'reported');
INSERT INTO `comments` VALUES (3, 1, 4, 1, '同意！特别是击败玛莲妮亚的时候，那种成就感真的太爽了！', 12, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (4, 1, 5, NULL, '游戏很棒，但是优化有点问题，希望能改进一下帧数。', 8, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (5, 1, 6, 1, '我觉得开放世界反而降低了游戏的紧凑感，不如黑魂3。', 5, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (6, 2, 2, NULL, '战斗系统太爽了！弹反的手感无与伦比，每次完美弹反都让人热血沸腾。', 38, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (7, 2, 7, NULL, '剑圣苇名一心打了我三天，但是通关后真的太有成就感了！', 30, '2026-01-20 20:26:21', '2026-01-21 13:44:24', 'normal');
INSERT INTO `comments` VALUES (8, 2, 8, 2, '弹反确实很爽，但是对手残玩家不太友好哈哈', 15, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (9, 2, 3, NULL, '日本战国时代的氛围营造得很好，音乐也很棒。', 18, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (10, 5, 2, NULL, '经过多次更新后，游戏已经好很多了。夜之城的氛围营造得非常棒，主线剧情也很感人。', 56, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (11, 5, 3, NULL, '刚发售时确实bug很多，但现在已经是一款优秀的RPG了。强烈推荐！', 42, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (12, 5, 4, 5, '同意，现在的版本已经很稳定了，而且DLC也很不错。', 21, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (13, 5, 9, NULL, '画面太震撼了，特别是开启光追后，夜之城美得不像话。', 33, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (15, 6, 2, NULL, '史诗级的RPG，剧情、画面、音乐都是顶级水准。血与酒DLC更是神作中的神作！', 89, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (16, 6, 3, NULL, '杰洛特和叶奈法的感情线太感人了，这才是真正的爱情故事。', 67, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (17, 6, 4, 6, '我选的特莉丝，哈哈哈', 34, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (18, 6, 5, NULL, '昆特牌太好玩了，差点忘了主线任务。', 78, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (19, 6, 11, 6, '血与酒的陶森特真的太美了，我在那里待了50个小时。', 45, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (20, 16, 2, NULL, '开放世界的标杆之作！自由度极高，你可以用各种创意方法解决问题。', 92, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (21, 16, 3, NULL, '物理引擎太有趣了，经常能发现一些意想不到的玩法。', 71, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (22, 16, 4, 16, '对！我用各种奇怪的方法打Boss，每次都有新发现。', 38, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (23, 16, 12, NULL, '神庙解谜设计得很巧妙，每个都让人眼前一亮。', 54, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (24, 4, 3, NULL, '父子情深的故事太感人了，战斗系统也很爽快。奎托斯的成长让人动容。', 63, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (25, 4, 5, NULL, '画面太震撼了，特别是那些Boss战，每一场都是视觉盛宴。', 47, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (26, 8, 5, NULL, '自由度太高了！每个选择都会影响剧情，重玩价值极高。', 58, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (27, 8, 11, NULL, '队友的故事都很精彩，特别是影心和阿斯代伦的支线。', 41, '2026-01-20 20:26:21', '2026-01-20 14:45:49', 'deleted');
INSERT INTO `comments` VALUES (28, 17, 11, NULL, '这是我玩过最有沉浸感的游戏，每个细节都做得极其用心。亚瑟的故事让我哭了。', 95, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (29, 17, 12, 17, '同感！特别是最后那段剧情，太催泪了。', 52, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (30, 18, 12, NULL, '剧情很有争议，但是游戏性和演出都是顶级的。值得一玩。', 44, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (31, 18, 13, NULL, '画面和动作捕捉太真实了，就像在看电影一样。', 36, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (32, 13, 9, NULL, '最好玩的大逃杀游戏！英雄技能设计得很有趣，团队配合很重要。', 51, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (34, 21, 13, NULL, '画面太美了！墨西哥的风景让人流连忘返，车辆手感也很棒。', 39, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (35, 25, 14, NULL, '超级治愈的游戏，玩了200小时还想继续玩。强烈推荐给压力大的朋友！', 87, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (36, 25, 2, 25, '我已经玩了500小时了，还在发现新内容，哈哈', 43, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'normal');
INSERT INTO `comments` VALUES (37, 1, 15, NULL, '这游戏就是垃圾，浪费钱！', 1, '2026-01-20 20:26:21', '2026-01-20 13:23:16', 'normal');
INSERT INTO `comments` VALUES (38, 5, 15, NULL, '骗钱的游戏，bug一堆！', 0, '2026-01-20 20:26:21', '2026-01-20 20:26:21', 'reported');
INSERT INTO `comments` VALUES (39, 1, 17, NULL, '还可以吧', 0, '2026-01-20 13:19:14', '2026-01-20 13:19:14', 'normal');
INSERT INTO `comments` VALUES (40, 1, 17, 1, '666', 0, '2026-01-20 13:33:51', '2026-01-20 13:33:51', 'normal');
INSERT INTO `comments` VALUES (41, 4, 17, NULL, '我觉得一般', 0, '2026-01-20 13:48:45', '2026-01-20 13:48:45', 'normal');
INSERT INTO `comments` VALUES (42, 8, 1, NULL, '游戏体验一般，需要更加沉浸式的设计', 0, '2026-01-20 15:15:30', '2026-01-21 15:11:33', 'normal');
INSERT INTO `comments` VALUES (43, 2, 1, 7, '666', 0, '2026-01-21 13:44:28', '2026-01-21 13:44:28', 'normal');
INSERT INTO `comments` VALUES (44, 8, 16, NULL, '还原度较高还不错', 0, '2026-01-21 14:59:32', '2026-01-21 14:59:32', 'normal');
INSERT INTO `comments` VALUES (45, 8, 16, 26, '评价很中肯，附议', 0, '2026-01-21 15:00:01', '2026-01-21 15:00:01', 'normal');

-- ----------------------------
-- Table structure for game_categories
-- ----------------------------
DROP TABLE IF EXISTS `game_categories`;
CREATE TABLE `game_categories`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '分类描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分类表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of game_categories
-- ----------------------------
INSERT INTO `game_categories` VALUES (1, '动作', '以快节奏战斗和反应速度为核心的游戏类型', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (2, '角色扮演', '玩家扮演角色，通过剧情和成长系统推进游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (3, '策略', '需要玩家运用智慧和战术规划的游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (4, '射击', '以枪械或远程武器为主要玩法的游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (5, '冒险', '探索未知世界，解谜和发现故事的游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (6, '体育', '模拟各类体育运动的游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (7, '竞速', '以速度竞技为核心的赛车类游戏', '2026-01-20 20:26:21');
INSERT INTO `game_categories` VALUES (8, '模拟', '模拟真实或虚拟场景的游戏', '2026-01-20 20:26:21');

-- ----------------------------
-- Table structure for game_ratings
-- ----------------------------
DROP TABLE IF EXISTS `game_ratings`;
CREATE TABLE `game_ratings`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `game_id` int NOT NULL COMMENT '游戏id',
  `user_id` int NOT NULL COMMENT '用户id',
  `gameplay_score` decimal(3, 1) NULL DEFAULT NULL COMMENT '可玩分',
  `graphics_score` decimal(3, 1) NULL DEFAULT NULL COMMENT '图形分',
  `story_score` decimal(3, 1) NULL DEFAULT NULL COMMENT '剧情分',
  `sound_score` decimal(3, 1) NULL DEFAULT NULL COMMENT '音效分',
  `overall_score` decimal(3, 1) NULL DEFAULT NULL COMMENT '综合评分',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_user_game_rating`(`game_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  CONSTRAINT `game_ratings_ibfk_1` FOREIGN KEY (`game_id`) REFERENCES `games` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `game_ratings_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `game_ratings_chk_1` CHECK ((`gameplay_score` >= 0) and (`gameplay_score` <= 10)),
  CONSTRAINT `game_ratings_chk_2` CHECK ((`graphics_score` >= 0) and (`graphics_score` <= 10)),
  CONSTRAINT `game_ratings_chk_3` CHECK ((`story_score` >= 0) and (`story_score` <= 10)),
  CONSTRAINT `game_ratings_chk_4` CHECK ((`sound_score` >= 0) and (`sound_score` <= 10)),
  CONSTRAINT `game_ratings_chk_5` CHECK ((`overall_score` >= 0) and (`overall_score` <= 10))
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏评分表' ROW_FORMAT = DYNAMIC;

