-- ----------------------------
-- Table structure for games
-- ----------------------------
DROP TABLE IF EXISTS `games`;
CREATE TABLE `games`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名称',
  `category_id` int NULL DEFAULT NULL COMMENT '分类id',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '介绍',
  `cover_image` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图',
  `images` json NULL COMMENT '游戏图集（JSON数组）',
  `release_date` date NULL DEFAULT NULL COMMENT '发布日期',
  `developer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '开发方',
  `publisher` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发行方',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` enum('published','draft') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'published' COMMENT '状态',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_title`(`title` ASC) USING BTREE,
  INDEX `idx_category`(`category_id` ASC) USING BTREE,
  CONSTRAINT `games_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `game_categories` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of games
-- ----------------------------
INSERT INTO `games` VALUES (1, '艾尔登法环', 1, '由FromSoftware开发的开放世界动作角色扮演游戏，结合了黑暗奇幻世界观和高难度战斗系统。玩家将在广阔的交界地探索，面对各种强大的敌人和Boss。', '/uploads/20260121/eaac2624d3884c04950e70fc7d943dc0.png', '[\"https://picsum.photos/800/450?random=1\", \"https://picsum.photos/800/450?random=2\", \"https://picsum.photos/800/450?random=3\", \"/uploads/20260121/38b7dacd8ad14e8da0b9881d7fbab018.png\"]', '2022-02-25', 'FromSoftware', 'Bandai Namco', '2026-01-20 20:26:21', '2026-01-21 14:46:19', 'published');
INSERT INTO `games` VALUES (2, '只狼：影逝二度', 1, '一款以日本战国时代为背景的动作冒险游戏，玩家扮演忍者只狼，使用独特的义手忍具和剑术对抗敌人。游戏以高难度和精妙的战斗系统著称。', '/uploads/20260121/736d186fb7b94acf8ce0b146f85b9bb7.png', '[\"https://picsum.photos/800/450?random=1\", \"https://picsum.photos/800/450?random=2\", \"https://picsum.photos/800/450?random=3\"]', '2019-03-22', 'FromSoftware', 'Activision', '2026-01-20 20:26:21', '2026-01-21 14:47:10', 'published');
INSERT INTO `games` VALUES (3, '鬼泣5', 1, '经典动作游戏系列的最新作，玩家可以操控但丁、尼禄和V三位角色，使用华丽的连招和技能消灭恶魔。', '/uploads/20260121/02b9fc22b5684e308de967ae29d39372.png', '[\"https://picsum.photos/800/450?random=1\", \"https://picsum.photos/800/450?random=2\", \"https://picsum.photos/800/450?random=3\"]', '2019-03-08', 'Capcom', 'Capcom', '2026-01-20 20:26:21', '2026-01-21 14:47:21', 'published');
INSERT INTO `games` VALUES (4, '战神：诸神黄昏', 1, '北欧神话题材的动作冒险游戏，讲述奎托斯父子在诸神黄昏来临之际的冒险故事。游戏拥有震撼的战斗场面和感人的剧情。', '/uploads/20260121/45f26c4eb99b4cfcb2c57ff0755bec94.png', '[\"https://picsum.photos/800/450?random=1\", \"https://picsum.photos/800/450?random=2\", \"https://picsum.photos/800/450?random=3\"]', '2022-11-09', 'Santa Monica Studio', 'Sony Interactive Entertainment', '2026-01-20 20:26:21', '2026-01-21 14:47:43', 'published');
INSERT INTO `games` VALUES (5, '赛博朋克2077', 2, '开放世界角色扮演游戏，设定在未来的夜之城。玩家扮演雇佣兵V，在这个充满霓虹灯和高科技的世界中展开冒险。', '/uploads/20260121/e0ad6c4b82b441dfbca9e47afe9c7f1c.png', '[\"https://picsum.photos/800/450?random=1\", \"https://picsum.photos/800/450?random=2\", \"https://picsum.photos/800/450?random=3\"]', '2020-12-10', 'CD Projekt Red', 'CD Projekt', '2026-01-20 20:26:21', '2026-01-21 14:47:56', 'published');
INSERT INTO `games` VALUES (6, '巫师3：狂猎', 2, '史诗级开放世界RPG，玩家扮演猎魔人杰洛特，在广阔的世界中寻找养女希里，同时完成各种支线任务。游戏以丰富的剧情和选择系统著称。', '/uploads/20260121/d5944c54e9c34e5996babb4faa8ec1e3.png', '[\"https://picsum.photos/800/450?random=4\", \"https://picsum.photos/800/450?random=5\"]', '2015-05-19', 'CD Projekt Red', 'CD Projekt', '2026-01-20 20:26:21', '2026-01-21 14:48:05', 'published');
INSERT INTO `games` VALUES (7, '最终幻想16', 2, '最终幻想系列的最新正统续作，采用动作战斗系统，讲述了一个关于召唤兽和王国纷争的史诗故事。', '/uploads/20260121/b55067f9510e4861a0ec9d2bb17d98e0.png', '[\"https://picsum.photos/800/450?random=4\", \"https://picsum.photos/800/450?random=5\"]', '2023-06-22', 'Square Enix', 'Square Enix', '2026-01-20 20:26:21', '2026-01-21 14:48:23', 'published');
INSERT INTO `games` VALUES (8, '博德之门3', 2, '基于龙与地下城规则的回合制RPG，拥有极高的自由度和丰富的剧情分支。玩家的每个选择都会影响故事的走向。', '/uploads/20260121/7829c853574a47c984ac434988a040e5.png', '[\"https://picsum.photos/800/450?random=4\", \"https://picsum.photos/800/450?random=5\"]', '2023-08-03', 'Larian Studios', 'Larian Studios', '2026-01-20 20:26:21', '2026-01-21 14:48:32', 'published');
INSERT INTO `games` VALUES (9, '文明6', 3, '回合制策略游戏，玩家领导一个文明从石器时代发展到信息时代，通过外交、战争、科技等手段争夺世界霸权。', '/uploads/20260121/7fb49f11210144969761e78697ddeb86.png', '[\"https://picsum.photos/800/450?random=4\", \"https://picsum.photos/800/450?random=5\"]', '2016-10-21', 'Firaxis Games', '2K Games', '2026-01-20 20:26:21', '2026-01-21 14:48:43', 'published');
INSERT INTO `games` VALUES (10, '全面战争：战锤3', 3, '结合回合制战略和即时战术的游戏，设定在战锤奇幻世界。玩家可以指挥各个种族的军队进行大规模战斗。', '/uploads/20260121/45a950598e3441e8a4d5dc940b71759e.png', '[\"https://picsum.photos/800/450?random=4\", \"https://picsum.photos/800/450?random=5\"]', '2022-02-17', 'Creative Assembly', 'Sega', '2026-01-20 20:26:21', '2026-01-21 14:48:51', 'published');
INSERT INTO `games` VALUES (11, '星际争霸2', 3, '经典即时战略游戏，拥有三个特色鲜明的种族和竞技性极强的多人对战模式。', '/uploads/20260121/da3d69988fb0455a9f678f3062bd4172.png', '[\"https://picsum.photos/800/450?random=6\"]', '2010-07-27', 'Blizzard Entertainment', 'Blizzard Entertainment', '2026-01-20 20:26:21', '2026-01-21 14:49:01', 'published');
INSERT INTO `games` VALUES (12, '使命召唤：现代战争2', 4, '第一人称射击游戏，以现代战争为背景，拥有紧张刺激的单人战役和多样化的多人模式。', '/uploads/20260121/d9841d3570b44d19a7a38fd369522a15.png', '[\"https://picsum.photos/800/450?random=6\"]', '2022-10-28', 'Infinity Ward', 'Activision', '2026-01-20 20:26:21', '2026-01-21 14:49:08', 'published');
INSERT INTO `games` VALUES (13, 'APEX英雄', 4, '免费的大逃杀射击游戏，玩家选择不同技能的英雄在竞技场中战斗，强调团队配合。', '/uploads/20260121/22130cf3cfb34d7e85a1b7663cc47ce8.png', '[\"https://picsum.photos/800/450?random=6\"]', '2019-02-04', 'Respawn Entertainment', 'Electronic Arts', '2026-01-20 20:26:21', '2026-01-21 14:49:16', 'published');
INSERT INTO `games` VALUES (14, '瓦洛兰特', 4, '5v5战术射击游戏，结合了精准射击和独特的角色技能，强调策略和团队配合。', '/uploads/20260121/58ae7cd2f85545f39203646cb90af58a.png', '[\"https://picsum.photos/800/450?random=6\"]', '2020-06-02', 'Riot Games', 'Riot Games', '2026-01-20 20:26:21', '2026-01-21 14:49:28', 'published');
INSERT INTO `games` VALUES (15, 'CS:GO', 4, '经典的竞技射击游戏，拥有庞大的玩家群体和成熟的电竞体系。', '/uploads/20260121/a2f7d10eb19b4179a1d90ee1b29b1a9b.png', '[\"https://picsum.photos/800/450?random=6\"]', '2012-08-21', 'Valve', 'Valve', '2026-01-20 20:26:21', '2026-01-21 14:49:37', 'published');
INSERT INTO `games` VALUES (16, '塞尔达传说：旷野之息', 5, '开放世界冒险游戏，玩家扮演林克在海拉尔大陆自由探索，解谜和战斗。游戏以高自由度和创意玩法著称。', '/uploads/20260121/5ff32e4976994cc7ad5fc9cd00e07d4d.png', '[]', '2017-03-03', 'Nintendo', 'Nintendo', '2026-01-20 20:26:21', '2026-01-21 14:49:45', 'published');
INSERT INTO `games` VALUES (17, '荒野大镖客：救赎2', 5, '开放世界西部题材游戏，讲述亡命之徒亚瑟·摩根的故事。游戏拥有极其细腻的画面和沉浸式的世界。', '/uploads/20260121/1de68bf95f9c42bda9871cf1e61843f3.png', '[]', '2018-10-26', 'Rockstar Games', 'Rockstar Games', '2026-01-20 20:26:21', '2026-01-21 14:49:53', 'published');
INSERT INTO `games` VALUES (18, '最后生还者2', 5, '末世生存冒险游戏，讲述艾莉的复仇之旅。游戏以深刻的剧情和出色的演出著称。', '/uploads/20260121/193f6b44d13e4cf990f2ba1cd996e517.png', '[]', '2020-06-19', 'Naughty Dog', 'Sony Interactive Entertainment', '2026-01-20 20:26:21', '2026-01-21 14:50:00', 'published');
INSERT INTO `games` VALUES (19, 'FIFA 23', 6, '足球模拟游戏，拥有真实的球员数据和球队授权，提供多种游戏模式。', '/uploads/20260121/72c30fba381d413a83be5077e345f29a.png', '[]', '2022-09-30', 'EA Sports', 'Electronic Arts', '2026-01-20 20:26:21', '2026-01-21 14:50:06', 'published');
INSERT INTO `games` VALUES (20, 'NBA 2K23', 6, '篮球模拟游戏，以真实的NBA球员和球队为基础，提供生涯模式和在线对战。', '/uploads/20260121/a76c7af7db6a45e599f7d16c4bec22ac.png', '[]', '2022-09-09', 'Visual Concepts', '2K Sports', '2026-01-20 20:26:21', '2026-01-21 14:50:15', 'published');
INSERT INTO `games` VALUES (21, '极限竞速：地平线5', 7, '开放世界赛车游戏，设定在墨西哥，拥有数百辆真实授权车辆和壮丽的风景。', '/uploads/20260121/2ef0133ece2c4bc79580aad6ba07149d.png', '[]', '2021-11-09', 'Playground Games', 'Xbox Game Studios', '2026-01-20 20:26:21', '2026-01-21 14:52:09', 'published');
INSERT INTO `games` VALUES (22, 'GT赛车7', 7, '真实赛车模拟游戏，以精确的物理引擎和大量真实赛道著称。', '/uploads/20260121/84108af074804b7a8d946809163373bc.png', '[]', '2022-03-04', 'Polyphony Digital', 'Sony Interactive Entertainment', '2026-01-20 20:26:21', '2026-01-21 14:52:20', 'published');
INSERT INTO `games` VALUES (23, '模拟人生4', 8, '生活模拟游戏，玩家创建和控制虚拟人物，体验他们的日常生活。', '/uploads/20260121/4df3992ab9c3435e8fece2dde29e59ff.png', '[]', '2014-09-02', 'Maxis', 'Electronic Arts', '2026-01-20 20:26:21', '2026-01-21 14:52:28', 'published');
INSERT INTO `games` VALUES (24, '微软飞行模拟', 8, '高度真实的飞行模拟游戏，使用真实地球数据，让玩家驾驶各种飞机环游世界。', '/uploads/20260121/0156745f4fcf4a10bdac237118858026.png', '[]', '2020-08-18', 'Asobo Studio', 'Xbox Game Studios', '2026-01-20 20:26:21', '2026-01-21 14:52:36', 'published');
INSERT INTO `games` VALUES (25, '星露谷物语', 8, '农场模拟游戏，玩家继承祖父的农场，种植作物、养殖动物、与村民交往。', '/uploads/20260121/3e3cca1b6c2f4876bdb67fb1732c7784.png', '[]', '2016-02-26', 'ConcernedApe', 'ConcernedApe', '2026-01-20 20:26:21', '2026-01-21 14:52:43', 'published');

-- ----------------------------
-- Table structure for reports
-- ----------------------------
DROP TABLE IF EXISTS `reports`;
CREATE TABLE `reports`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `comment_id` int NOT NULL COMMENT '评论id',
  `user_id` int NOT NULL COMMENT '用户id',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '举报原因',
  `status` enum('pending','processed','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'pending' COMMENT '状态',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `processed_at` timestamp NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `comment_id`(`comment_id` ASC) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  CONSTRAINT `reports_ibfk_1` FOREIGN KEY (`comment_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `reports_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '举报表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of reports
-- ----------------------------
INSERT INTO `reports` VALUES (1, 27, 2, '内容不当，恶意攻击游戏', 'processed', '2026-01-20 20:26:21', '2026-01-20 14:45:49');
